// Free-slot computation for broker viewings.
//
// This module is pure: it takes a normalized availability record (see
// production/lib/broker-availability.mjs), the viewings already on the broker's
// calendar, and a date range, and returns the bookable slots. It never reads a
// file, never writes one, and never books anything.
//
// Time zone handling
// ------------------
// A broker's working hours are wall-clock times in the office time zone
// ("09:00 to 18:00" means whatever 09:00 is in Sofia that day). Slots are
// generated by first converting each day's window boundaries to real instants,
// then stepping forward in REAL time. That is what makes the calculation
// correct across a daylight-saving change:
//
//   * On the spring-forward day a window that contains the transition is one
//     real hour shorter, so it yields one step fewer. No slot is ever produced
//     at a local time that does not exist.
//   * On the fall-back day the same window is one real hour longer and yields
//     one step more. The repeated wall-clock hour appears twice with two
//     distinct instants, which is what actually happens.
//   * A window that does not contain the transition keeps its local start and
//     end but its UTC instants move by an hour, which is also correct.
//
// Everything the caller sees carries both the instant (`starts_at`, UTC ISO)
// and the local label (`local_start`), so a screen never has to redo this.

const HHMM = /^([01]\d|2[0-3]):([0-5]\d)$/;
const ISO_DATE = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const MINUTE_MS = 60 * 1000;
const DAY_MS = 24 * 60 * MINUTE_MS;

export const DEFAULT_VIEWING_DURATION_MINUTES = 60;
export const DEFAULT_SLOT_STEP_MINUTES = 30;
// A range longer than this is refused rather than silently truncated: an
// unbounded range is a denial-of-service shape on a public route.
export const MAX_SLOT_RANGE_DAYS = 62;

export function assertTimeZone(timeZone) {
  const zone = String(timeZone || "").trim();
  if (!zone) throw new Error("A time zone is required to compute free slots");
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: zone });
  } catch {
    throw new Error(`${zone} is not a known IANA time zone`);
  }
  return zone;
}

export function assertIsoDate(value, label) {
  const date = String(value || "").trim();
  if (!ISO_DATE.test(date)) throw new Error(`${label} must be a YYYY-MM-DD date`);
  if (Number.isNaN(Date.parse(`${date}T00:00:00Z`))) throw new Error(`${label} must be a real calendar date`);
  return date;
}

export function assertClockTime(value, label) {
  const time = String(value || "").trim();
  if (!HHMM.test(time)) throw new Error(`${label} must be a HH:MM time of day`);
  return time;
}

export function clockMinutes(value) {
  const [hour, minute] = assertClockTime(value, "time").split(":").map(Number);
  return hour * 60 + minute;
}

const partsFormatterCache = new Map();

function partsFormatter(timeZone) {
  let formatter = partsFormatterCache.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    partsFormatterCache.set(timeZone, formatter);
  }
  return formatter;
}

// The wall-clock reading of an instant in a time zone, plus the ISO weekday.
export function zonedParts(instantMs, timeZone) {
  const parts = Object.fromEntries(
    partsFormatter(timeZone)
      .formatToParts(new Date(instantMs))
      .filter((part) => part.type !== "literal")
      .map((part) => [part.type, Number(part.value)]),
  );
  const hour = parts.hour % 24;
  const date = `${String(parts.year).padStart(4, "0")}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`;
  const weekday = new Date(Date.UTC(parts.year, parts.month - 1, parts.day)).getUTCDay() || 7;
  return {
    year: parts.year,
    month: parts.month,
    day: parts.day,
    hour,
    minute: parts.minute,
    second: parts.second,
    date,
    time: `${String(hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}`,
    weekday,
  };
}

// Offset of the time zone from UTC, in milliseconds, at a given instant.
export function timeZoneOffsetMs(instantMs, timeZone) {
  const parts = zonedParts(instantMs, timeZone);
  const asIfUtc = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second);
  // Date.UTC rounds to the second; the instant may carry milliseconds.
  return asIfUtc - (instantMs - (instantMs % 1000));
}

// The instant at which the given wall clock reading occurs in the time zone.
// Two passes settle the case where the naive guess lands on the other side of a
// daylight-saving transition. A wall clock time that does not exist (the spring
// forward gap) resolves to the instant the clock jumps to, so a window boundary
// inside the gap still produces a usable, real instant.
export function zonedWallClockToUtc(date, time, timeZone) {
  const [year, month, day] = assertIsoDate(date, "date").split("-").map(Number);
  const [hour, minute] = assertClockTime(time, "time").split(":").map(Number);
  const naive = Date.UTC(year, month - 1, day, hour, minute);
  const firstOffset = timeZoneOffsetMs(naive, timeZone);
  const firstGuess = naive - firstOffset;
  const secondOffset = timeZoneOffsetMs(firstGuess, timeZone);
  if (secondOffset === firstOffset) return firstGuess;
  const secondGuess = naive - secondOffset;
  // If neither offset reproduces the requested wall clock, the local time falls
  // inside the spring-forward gap. Both guesses then name the same instant just
  // after the jump; take the later one so the window never starts in the past.
  const reproduces = (instant) => zonedParts(instant, timeZone).time === assertClockTime(time, "time");
  if (reproduces(secondGuess)) return secondGuess;
  if (reproduces(firstGuess)) return firstGuess;
  return Math.max(firstGuess, secondGuess);
}

export function addDays(date, count) {
  const [year, month, day] = assertIsoDate(date, "date").split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1, day) + count * DAY_MS);
  return shifted.toISOString().slice(0, 10);
}

function isoWeekdayOf(date) {
  const [year, month, day] = assertIsoDate(date, "date").split("-").map(Number);
  return new Date(Date.UTC(year, month - 1, day)).getUTCDay() || 7;
}

function windowsForDate(availability, date) {
  const weekday = isoWeekdayOf(date);
  const exception = (availability.exceptions || []).find((row) => row.date === date) || null;
  if (exception && exception.kind === "closed") {
    return { weekday, windows: [], closed: true, exception, reason: exception.reason || "closed" };
  }
  if (exception && exception.kind === "hours") {
    const windows = [...(exception.windows || [])];
    return { weekday, windows, closed: windows.length === 0, exception, reason: exception.reason || "changed_hours" };
  }
  const windows = (availability.weekly_hours || [])
    .filter((row) => row.weekday === weekday)
    .map((row) => ({ start: row.start, end: row.end }));
  return { weekday, windows, closed: windows.length === 0, exception: null, reason: windows.length ? null : "not_working" };
}

function busyIntervals(viewings, brokerId, durationMinutes) {
  return (viewings || [])
    .filter((row) => row && row.broker === brokerId && row.starts_at)
    // A no-show already happened; it does not reserve future time.
    .filter((row) => row.status !== "no_show")
    .map((row) => {
      const start = Date.parse(row.starts_at);
      if (!Number.isFinite(start)) return null;
      // The ledger stores only a start. Existing viewings are treated as
      // occupying the same duration the caller is asking to book, which is the
      // conservative reading: it never hands out a slot that overlaps one.
      const minutes = Number.isFinite(Number(row.duration_minutes)) ? Number(row.duration_minutes) : durationMinutes;
      return { id: row.id || null, start, end: start + minutes * MINUTE_MS };
    })
    .filter(Boolean);
}

function overlapping(busy, start, end) {
  return busy.find((interval) => interval.start < end && start < interval.end) || null;
}

/**
 * Bookable slots for one broker over a date range.
 *
 * @param {object} options
 * @param {object} options.availability normalized availability (broker_id, timezone, weekly_hours, exceptions, source)
 * @param {Array}  options.viewings     viewing rows or derived viewing states ({ id, broker, starts_at, status })
 * @param {string} options.from         first day, YYYY-MM-DD, in the office time zone
 * @param {string} options.to           last day, inclusive, YYYY-MM-DD
 * @param {number} options.durationMinutes length of the viewing being booked
 * @param {number} options.stepMinutes  spacing between candidate starts
 * @param {string} options.now          ISO instant; slots before it are not bookable
 * @param {number} options.leadTimeMinutes minimum notice before the first bookable slot
 * @param {number} options.limit        maximum number of available slots to return
 */
export function computeFreeSlots({
  availability,
  viewings = [],
  from,
  to,
  durationMinutes = DEFAULT_VIEWING_DURATION_MINUTES,
  stepMinutes = DEFAULT_SLOT_STEP_MINUTES,
  now = new Date().toISOString(),
  leadTimeMinutes = 0,
  limit = null,
} = {}) {
  if (!availability || typeof availability !== "object") throw new Error("Free-slot computation requires broker availability");
  const brokerId = String(availability.broker_id || "").trim();
  if (!brokerId) throw new Error("Free-slot computation requires a broker id");
  const timeZone = assertTimeZone(availability.timezone);
  const duration = Number(durationMinutes);
  if (!Number.isInteger(duration) || duration < 5 || duration > 8 * 60) {
    throw new Error("durationMinutes must be a whole number of minutes between 5 and 480");
  }
  const step = Number(stepMinutes);
  if (!Number.isInteger(step) || step < 5 || step > 8 * 60) {
    throw new Error("stepMinutes must be a whole number of minutes between 5 and 480");
  }
  const lead = Number(leadTimeMinutes);
  if (!Number.isInteger(lead) || lead < 0) throw new Error("leadTimeMinutes must be zero or a whole number of minutes");
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new Error("now must be an ISO timestamp");
  const firstDate = assertIsoDate(from, "from");
  const lastDate = assertIsoDate(to, "to");
  if (Date.parse(`${lastDate}T00:00:00Z`) < Date.parse(`${firstDate}T00:00:00Z`)) throw new Error("to cannot precede from");
  const dayCount = Math.round((Date.parse(`${lastDate}T00:00:00Z`) - Date.parse(`${firstDate}T00:00:00Z`)) / DAY_MS) + 1;
  if (dayCount > MAX_SLOT_RANGE_DAYS) throw new Error(`The range must not exceed ${MAX_SLOT_RANGE_DAYS} days`);
  const maxSlots = limit === null || limit === undefined ? null : Number(limit);
  if (maxSlots !== null && (!Number.isInteger(maxSlots) || maxSlots < 1)) throw new Error("limit must be a positive whole number");

  const busy = busyIntervals(viewings, brokerId, duration);
  const earliest = nowMs + lead * MINUTE_MS;
  const days = [];
  const available = [];

  for (let index = 0; index < dayCount; index += 1) {
    const date = addDays(firstDate, index);
    const shape = windowsForDate(availability, date);
    const slots = [];
    for (const window of shape.windows) {
      const windowStart = zonedWallClockToUtc(date, window.start, timeZone);
      const windowEnd = zonedWallClockToUtc(date, window.end, timeZone);
      if (windowEnd <= windowStart) throw new Error(`Working window ${window.start}-${window.end} on ${date} does not end after it starts`);
      for (let start = windowStart; start + duration * MINUTE_MS <= windowEnd; start += step * MINUTE_MS) {
        const end = start + duration * MINUTE_MS;
        const clash = overlapping(busy, start, end);
        const past = start < earliest;
        const startParts = zonedParts(start, timeZone);
        const endParts = zonedParts(end, timeZone);
        const slot = {
          broker_id: brokerId,
          starts_at: new Date(start).toISOString(),
          ends_at: new Date(end).toISOString(),
          duration_minutes: duration,
          local_date: startParts.date,
          local_start: startParts.time,
          local_end: endParts.time,
          timezone: timeZone,
          available: !clash && !past,
          blocked_by: clash ? "viewing" : past ? "lead_time" : null,
          viewing_id: clash ? clash.id : null,
        };
        slots.push(slot);
        if (slot.available) available.push(slot);
      }
    }
    days.push({
      date,
      weekday: shape.weekday,
      closed: shape.closed,
      reason: shape.reason,
      exception: shape.exception,
      windows: shape.windows,
      slots,
      open_slots: slots.filter((slot) => slot.available).length,
    });
  }

  const limited = maxSlots === null ? available : available.slice(0, maxSlots);
  return {
    broker_id: brokerId,
    timezone: timeZone,
    availability_source: availability.source || "broker_recorded",
    duration_minutes: duration,
    step_minutes: step,
    lead_time_minutes: lead,
    from: firstDate,
    to: lastDate,
    generated_at: new Date(nowMs).toISOString(),
    days,
    slots: limited,
    summary: {
      days: days.length,
      open_days: days.filter((day) => !day.closed).length,
      candidate_slots: days.reduce((total, day) => total + day.slots.length, 0),
      available_slots: available.length,
      returned_slots: limited.length,
      blocked_by_viewings: days.reduce((total, day) => total + day.slots.filter((slot) => slot.blocked_by === "viewing").length, 0),
    },
  };
}
